286	// =========================================================================
287	//  Stochastic rounding to BF16 (branchless via PTX hash_prng).
288	// =========================================================================
289	
290	__device__ __forceinline__ __nv_bfloat16 round_bf16_stochastic(
291	    float v, uint32_t prng_key
292	) {
293	    return float_to_bf16_stochastic(v, prng_key);
