158	/**
159	* ///////////////////////////////
160	* // make_gmma_desc<Major::MN> //
161	* ///////////////////////////////
162	* Each GmmaDescriptor Major-MN describes a canonical layout of the form
163	*
164	* LayoutType::INTERLEAVE   : Swizzle<0,4,3> o smem_ptr o ((T,1,m),(8,k)):((1,T,SBO),(1T,LBO))
165	* LayoutType::B32          : Swizzle<1,4,3> o smem_ptr o ((T,2,m),(8,k)):((1,T,LBO),(2T,SBO))
166	* LayoutType::B64          : Swizzle<2,4,3> o smem_ptr o ((T,4,m),(8,k)):((1,T,LBO),(4T,SBO))
167	* LayoutType::B128         : Swizzle<3,4,3> o smem_ptr o ((T,8,m),(8,k)):((1,T,LBO),(8T,SBO))
168	*
169	* where
170	*   T  : sizeof(uint128_t) / sizeof(value_type)
171	*   m  : integer in [1,16] corresponding to GMMA shape
172	*   k  : integer in [1,32] corresponding to GMMA shape
173	*   SBO: stride byte offset
174	*   LBO: leading byte offset
175	*
176	* See GMMA::Layout_MN_XXX_Atom<value_type> for building canonical GmmaDescriptor Major-MN layouts.
177	* For example,
178	*   auto smem_layout = tile_to_shape(Layout_MN_SW128_Atom<value_type>{}, Shape<_128,_64>{});
179	* is guaranteed to be accepted by make_gmma_desc<Major::MN> for appropriate value_type.
180	*
181	* //////////////////////////////
182	* // make_gmma_desc<Major::K> //
183	* //////////////////////////////
184	* Each GmmaDescriptor Major-K describes a canonical layout of the form
185	*
186	* LayoutType::INTERLEAVE : Swizzle<0,4,3> o smem_ptr o ((8,m),(T,2)):((1T,SBO),(1,LBO))
187	* LayoutType::B32        : Swizzle<1,4,3> o smem_ptr o ((8,m),(T,2)):((2T,SBO),(1, T ))
188	* LayoutType::B64        : Swizzle<2,4,3> o smem_ptr o ((8,m),(T,2)):((4T,SBO),(1, T ))
189	* LayoutType::B128       : Swizzle<3,4,3> o smem_ptr o ((8,m),(T,2)):((8T,SBO),(1, T ))
190	*
191	* See GMMA::Layout_K_XXX_Atom<value_type> for building canonical GmmaDescriptor Major-K layouts.
192	* For example,
193	*   auto smem_layout = tile_to_shape(Layout_K_SW128_Atom<value_type>{}, Shape<_128,_64>{});
194	* is guaranteed to be accepted by make_gmma_desc<Major::K> for appropriate value_type.
195	*/
196	template <Major MajorMode, class TEngine, class TLayout>
197	CUTE_HOST_DEVICE constexpr
198	GmmaDescriptor
199	make_gmma_desc(Tensor<TEngine,TLayout> const& tensor)
200	{
201	  static_assert(is_smem<TEngine>::value, "GMMA Descriptors can only be constructed on smem.");
202	  static_assert(TLayout::rank == 2, "GMMA Descriptors can only be constructed on rank-2 tensors.");
203	  using value_type = typename TEngine::value_type;
204	
205	  Tensor u128_tensor = recast<uint128_t const>(tensor);
206	
207	  // Result
208	  GmmaDescriptor desc;
209	
210	  // Layout type
211	  constexpr LayoutType LAYOUT_TYPE = layout_type(u128_tensor);
212	  desc.bitfield.layout_type_ = uint8_t(LAYOUT_TYPE);
213	
214	  // Start address (4LSB not included)
215	  uint32_t start_address = cast_smem_ptr_to_uint(raw_pointer_cast(u128_tensor.data()));
216	  desc.bitfield.start_address_ = static_cast<uint16_t>(start_address >> 4);
217	
218	  constexpr uint8_t base_offset = 0;
219	  desc.bitfield.base_offset_ = base_offset;
220	
221	  // LayoutType meta
222	  constexpr int W = LAYOUT_TYPE == LayoutType::INTERLEAVE ? 1 :
223	                    LAYOUT_TYPE == LayoutType::B32        ? 2 :
224	                    LAYOUT_TYPE == LayoutType::B64        ? 4 :
225	                    LAYOUT_TYPE == LayoutType::B128       ? 8 : -1;
226	
227	  if constexpr (MajorMode == Major::MN)
228	  {
229	    /* In units of uint128_t, each GmmaDescriptor Major-MN describes a canonical layout of the form
230	     *
231	     * LayoutType::INTERLEAVE         : Swizzle<0,4,3> o smem_ptr o ((1,n),(8,k)):((X,SBO),(1,LBO))
232	     * LayoutType::B32                : Swizzle<1,4,3> o smem_ptr o ((2,n),(8,k)):((1,LBO),(2,SBO))
233	     * LayoutType::B64                : Swizzle<2,4,3> o smem_ptr o ((4,n),(8,k)):((1,LBO),(4,SBO))
234	     * LayoutType::B128               : Swizzle<3,4,3> o smem_ptr o ((8,n),(8,k)):((1,LBO),(8,SBO))
235	     */
236	    static_assert(size<1>(u128_tensor) == Int<(256 / cute::sizeof_bits<value_type>::value)>{} || // A and B in dense MMA
237	                  size<1>(u128_tensor) == Int<(128 / cute::sizeof_bits<value_type>::value)>{} || // A in sparse MMA
238	                  size<1>(u128_tensor) == Int<(512 / cute::sizeof_bits<value_type>::value)>{},   // B in sparse MMA
239	                         "Not a canonical GMMA_MN Layout: Expected K-size 256/sizeof_bits<T> for dense or (128|512)/sizeof_bits<T> for sparse.");
240	
241	    // Construct the canonical GMMA T Layout with shape ((W,n),(8,2))
242	    Layout canonical_layout = logical_divide(layout(u128_tensor), make_tile(Layout<Int<W>,_1>{}, Layout<Int<8>,_1>{}));
243	
244	    // Check ranks of canonical
245	    CUTE_STATIC_ASSERT_V(rank<0>(canonical_layout) == Int<2>{}, "Not a canonical GMMA_MN Layout: No flat offset mode");
246	    CUTE_STATIC_ASSERT_V(rank<1>(canonical_layout) == Int<2>{}, "Not a canonical GMMA_MN Layout: No flat offset mode");
247	    // Check canonical mode strides
248	    constexpr uint32_t stride_00 = stride<0,0>(canonical_layout);
249	    constexpr uint32_t expected_stride_00 = LAYOUT_TYPE == LayoutType::INTERLEAVE ? stride<0,0>(canonical_layout) : 1;
250	    static_assert(stride_00 == expected_stride_00, "Not a canonical GMMA_MN Layout: Expected stride failure.");
251	    constexpr uint32_t stride_10 = stride<1,0>(canonical_layout);
252	    constexpr uint32_t expected_stride_10 = W;
253	    static_assert(stride_10 == expected_stride_10, "Not a canonical GMMA_MN Layout: Expected stride failure.");
254	
255	    // stride dimension byte offset and leading dimension byte offset (4LSB not included == uint128_t units)
256	    constexpr uint32_t stride_01 = stride<0,1>(canonical_layout);
257	    constexpr uint32_t stride_11 = stride<1,1>(canonical_layout);
258	
259	    desc.bitfield.stride_byte_offset_  = (LAYOUT_TYPE == LayoutType::INTERLEAVE) ? stride_01 : stride_11;
260	    desc.bitfield.leading_byte_offset_ = (LAYOUT_TYPE == LayoutType::INTERLEAVE) ? stride_11 : stride_01;
261	  }
262	  else if constexpr (MajorMode == Major::K)
263	  {
264	    /* In units of uint128_t, each GmmaDescriptor Major-K describes a canonical layout of the form
265	     *
266	     * LayoutType::INTERLEAVE    : Swizzle<0,4,3> o smem_ptr o ((8,n),2):((1,SBO),LBO)
267	     * LayoutType::B32           : Swizzle<1,4,3> o smem_ptr o ((8,n),2):((2,SBO),1)
268	     * LayoutType::B64           : Swizzle<2,4,3> o smem_ptr o ((8,n),2):((4,SBO),1)
269	     * LayoutType::B128          : Swizzle<3,4,3> o smem_ptr o ((8,n),2):((8,SBO),1)
270	     */
271	    CUTE_STATIC_ASSERT_V(size<0>(u128_tensor) % Int<8>{} == Int<0>{},          // N|M size
272	                         "Not a canonical GMMA_K Layout: Expected MN-size multiple of 8.");
273	    CUTE_STATIC_ASSERT_V(size<1>(u128_tensor) == Int<2>{} || size<1>(u128_tensor) == Int<4>{},      // K   size
274	                         "Not a canonical GMMA_K Layout: Expected K-size 2 for dense or 4 for sparse (in units of uint128_t).");
275	
276	    // Construct the canonical GMMA N Layout with shape ((8,n),(2,1))
277	    Layout canonical_layout = logical_divide(layout(u128_tensor), make_tile(Layout<_8,_1>{}, Layout<_2,_1>{}));
278	
279	    // Check ranks of canonical
280	    CUTE_STATIC_ASSERT_V(rank<0>(canonical_layout) == Int<2>{}, "Not a canonical GMMA_K Layout: No flat offset mode");
281	    CUTE_STATIC_ASSERT_V(rank<1>(canonical_layout) == Int<2>{}, "Not a canonical GMMA_K Layout: No flat offset mode");
282	    // Check canonical mode strides
283	    constexpr uint32_t stride_00 = stride<0,0>(canonical_layout);
284	    constexpr uint32_t expected_stride_00 = W;
285	    static_assert(stride_00 == expected_stride_00, "Not a canonical GMMA_K Layout: Expected stride failure.");
286	    constexpr uint32_t stride_10 = stride<1,0>(canonical_layout);
287	    constexpr uint32_t expected_stride_10 = (LAYOUT_TYPE == LayoutType::INTERLEAVE) ? stride<1,0>(canonical_layout) : 1;
288	    static_assert(stride_10 == expected_stride_10, "Not a canonical GMMA_K Layout: Expected stride failure.");
289	
290	    // stride dimension byte offset and leading dimension byte offset (4LSB not included == uint128_t units)
291	    constexpr uint32_t stride_01 = stride<0,1>(canonical_layout);
292	
293	    desc.bitfield.stride_byte_offset_  = stride_01;
294	    desc.bitfield.leading_byte_offset_ = stride_10;
295	  } else {
296	    static_assert(MajorMode != Major::MN && MajorMode != Major::K, "Unrecognized MajorMode!");
297	  }
298	
299	#if 0
300	  // DEBUG and SANITY
301	  assert((start_address & 0b0000001111) == 0); // Must be 16B aligned (4LSB are 0) no negotiation
302	  assert((start_address & 0b1110000000) == 0); // Assert base_offset is 0, generalize later
303	  if (thread0()) {
304	    print("smem_desc input     tensor: "); print(tensor.data()); print(" o "); print(tensor.layout()); print("\n");
305	    print("smem_desc uint128_t tensor: "); print(u128_tensor.data()); print(" o "); print(u128_tensor.layout()); print("\n");
306	    //print("     desc canonical layout: "); print(canonical_layout); print("\n");
307	    print(desc);
308	  }
309	#endif
310	
311	  return desc;
312	}
