318	struct DescriptorIterator
319	{
320	  using reference    = GmmaDescriptor;
321	  using element_type = GmmaDescriptor;
322	  using value_type   = GmmaDescriptor;
323	
324	  GmmaDescriptor desc_;
325	
326	  // Dereference returns the GmmaDescriptor
327	  CUTE_HOST_DEVICE constexpr
328	  reference operator*() const { return desc_; }
329	
330	  // Advance and return a new GmmaDescriptor
331	  template <class Index>
332	  CUTE_HOST_DEVICE constexpr
333	  reference operator[](Index const& i) const { return *(*this + i); }
334	
335	  // Return an advanced iterator
336	  template <class Index>
337	  CUTE_HOST_DEVICE constexpr
338	  DescriptorIterator operator+(Index const& offset) const
339	  {
340	    return { GmmaDescriptor{desc_ + uint64_t(offset)} };
341	  }
342	};
343	
344	template <class T>
345	CUTE_HOST_DEVICE constexpr
346	GmmaDescriptor
347	raw_pointer_cast(DescriptorIterator const& ptr) {
348	  return ptr.desc_;
349	}
