351	// Recast a DescriptorIterator Tensor to uint64_t, it's RegType in mma_unpack
352	template <class NewT>
353	CUTE_HOST_DEVICE constexpr
354	DescriptorIterator
355	recast_ptr(DescriptorIterator const& iter) {
356	  static_assert(is_same<NewT, uint64_t>::value, "Can only cast GmmaDescriptorIterator to uint64_t.");
357	  return iter;  // Do nothing, it will still dereference to GmmaDescriptor and decay to uint64_t
358	}
