372	// Customization point for creating a GMMA::smem_desc Tensor
373	template <SM90::GMMA::Major MajorMode>
374	struct MakeTensor<SM90::GMMA::smem_desc<MajorMode>>
375	{
376	  template <class TEngine, class TLayout>
377	  CUTE_HOST_DEVICE constexpr auto
378	  operator()(Tensor<TEngine,TLayout> const& smem_tensor)
379	  {
380	    static_assert(is_smem<TEngine>::value, "Expected SMEM Tensor to construct a GMMA Desc Tensor");
381	    return make_tensor(SM90::GMMA::DescriptorIterator{SM90::GMMA::make_gmma_desc<MajorMode>(tensor<0>(smem_tensor))},
382	                       replace<0>(recast<uint128_t const>(smem_tensor).layout(), Layout<_1,_0>{}));
383	  }
384	};
