392	//
393	// Specialized mma_unpack implementation for SM90 GMMA instructions
394	//
395	
396	template <class MMA_Op, class... MMA_Args,
397	          class TD, class DLayout,
398	          class TA, class ALayout,
399	          class TB, class BLayout,
400	          class TC, class CLayout>
401	CUTE_HOST_DEVICE constexpr
402	void
403	mma_unpack(MMA_Traits<MMA_Op, MMA_Args...> const& traits,
404	           Tensor<TD, DLayout>      & D,
405	           Tensor<TA, ALayout> const& A,
406	           Tensor<TB, BLayout> const& B,
407	           Tensor<TC, CLayout> const& C)
408	{
409	  static_assert(is_rmem<TD>::value, "Expected registers in MMA_Atom::call");
410	  static_assert(is_rmem<TA>::value, "Expected registers in MMA_Atom::call");
411	  static_assert(is_rmem<TB>::value, "Expected registers in MMA_Atom::call");
412	  static_assert(is_rmem<TC>::value, "Expected registers in MMA_Atom::call");
413	
414	  // Register value types from the MMA_Operation register arrays
415	  using RegTypeA = typename remove_extent<typename MMA_Op::ARegisters>::type;
416	  using RegTypeB = typename remove_extent<typename MMA_Op::BRegisters>::type;
417	  using RegTypeC = typename remove_extent<typename MMA_Op::CRegisters>::type;
418	
419	  // SM90 GMMA take three arguments rather than four, try to assert C and D are aliased
420	  static_assert(is_same<typename TD::value_type, typename TC::value_type>::value, "GMMA C and D value_type must match.");
421	  static_assert(is_same<DLayout, CLayout>::value, "GMMA C and D layouts must match.");
422	  // assert((void*)&C == (void*)&D);
423	
424	  Tensor rA = recast<RegTypeA>(A);
425	  Tensor rB = recast<RegTypeB>(B);
426	  Tensor rC = recast<RegTypeC>(D);  // NOTE: D and C are same, so use mutable D
427	
428	  constexpr int RegNumA = extent<typename MMA_Op::ARegisters>::value;
429	  constexpr int RegNumB = extent<typename MMA_Op::BRegisters>::value;
430	  constexpr int RegNumC = extent<typename MMA_Op::CRegisters>::value;
431	
432	  CUTE_STATIC_ASSERT_V(size(rA) == Int<RegNumA>{});
433	  CUTE_STATIC_ASSERT_V(size(rB) == Int<RegNumB>{});
434	  CUTE_STATIC_ASSERT_V(size(rC) == Int<RegNumC>{});
435	
436	  detail::explode(MMA_Op::fma,
437	                  rA, make_int_sequence<RegNumA>{},
438	                  rB, make_int_sequence<RegNumB>{},
439	                  rC, make_int_sequence<RegNumC>{},
